import React, {useEffect, useState} from 'react'
import s2 from '../../s1-main/App.module.css'
import s from './HW14.module.css'
import axios from 'axios'
import SuperDebouncedInput from './common/c8-SuperDebouncedInput/SuperDebouncedInput'
import {useSearchParams} from 'react-router-dom'

const getTechs = (find: string) => {
    return axios
        .get<{ techs: string[] }>(
            'https://samurai.it-incubator.io/api/3.0/homework/test2',
            { params: { find } }
        )
        .catch((e) => {
            alert(e.response?.data?.errorText || e.message)
        })
}

const HW14 = () => {
    const [find, setFind] = useState('')
    const [isLoading, setIsLoading] = useState(false)
    const [searchParams, setSearchParams] = useSearchParams()
    const [techs, setTechs] = useState<string[]>([])

    const sendQuery = async (value: string) => {
        setIsLoading(true)
        const res = await getTechs(value)
        if (res?.data.techs) {
            setTechs(res.data.techs)
        } else {
            setTechs([])
        }
        setIsLoading(false)
    }

    const onChangeText = (value: string) => {
        setFind(value)
        const params = value ? { find: value } : {}
        setSearchParams(params as any) // обхід TS помилки
    }

    useEffect(() => {
        const params = Object.fromEntries(searchParams)
        const findFromParams = params.find || ''
        setFind(findFromParams)
        sendQuery(findFromParams)
    }, []) // searchParams не змінюється в процесі, можна не додавати в залежності

    const mappedTechs = techs.map(t => (
        <div key={t} id={`hw14-tech-${t}`} className={s.tech}>
            {t}
        </div>
    ))

    return (
        <div id={'hw14'}>
            <div className={s2.hwTitle}>Homework #14</div>

            <div className={s2.hw}>
                <SuperDebouncedInput
                    id={'hw14-super-debounced-input'}
                    value={find}
                    onChangeText={onChangeText}
                    onDebouncedChange={sendQuery}
                />

                <div id={'hw14-loading'} className={s.loading}>
                    {isLoading ? '...ищем' : <br />}
                </div>

                <div id="hw14-tech-list">
                    {mappedTechs}
                </div>
            </div>
        </div>
    )
}

export default HW14
