import React, {useEffect, useState} from 'react'
import s2 from '../../s1-main/App.module.css'
import s from './HW15.module.css'
import axios from 'axios'
import SuperPagination from './common/c9-SuperPagination/SuperPagination'
import {useSearchParams} from 'react-router-dom'
import SuperSort from './common/c10-SuperSort/SuperSort'

type TechType = {
    id: number
    tech: string
    developer: string
}

type ParamsType = {
    sort: string
    page: number
    count: number
}

const getTechs = async (params: ParamsType) => {
    try {
        const response = await axios.get<{ techs: TechType[], totalCount: number }>(
            'https://samurai.it-incubator.io/api/3.0/homework/test3',
            { params }
        )
        return response.data
    } catch (e) {
        console.error(e)
        return { techs: [], totalCount: 0 }
    }
}

const HW15 = () => {
    const [searchParams, setSearchParams] = useSearchParams()
    const [loading, setLoading] = useState(false)
    const [techs, setTechs] = useState<TechType[]>([])
    const [totalCount, setTotalCount] = useState(0)

    // Initialize state from URL params
    const initialPage = parseInt(searchParams.get('page') || '1', 10)
    const initialCount = parseInt(searchParams.get('count') || '4', 10)
    const initialSort = searchParams.get('sort') || ''

    const [page, setPage] = useState(initialPage)
    const [count, setCount] = useState(initialCount)
    const [sort, setSort] = useState(initialSort)

    const loadData = async () => {
        setLoading(true)
        const data = await getTechs({ page, count, sort })
        setTechs(data.techs)
        setTotalCount(data.totalCount)
        setLoading(false)
    }

    useEffect(() => {
        loadData()
    }, [page, count, sort])

    const handlePageChange = (newPage: number, newCount: number) => {
        const params = new URLSearchParams()
        params.set('page', newPage.toString())
        params.set('count', newCount.toString())
        if (sort) params.set('sort', sort)

        setPage(newPage)
        setCount(newCount)
        setSearchParams(params)
    }

    const handleSortChange = (newSort: string) => {
        const params = new URLSearchParams()
        params.set('page', '1')
        params.set('count', count.toString())
        if (newSort) params.set('sort', newSort)

        setPage(1)
        setSort(newSort)
        setSearchParams(params)
    }

    const mappedTechs = techs.map(t => (
        <div key={t.id} className={s.row}>
            <div id={'hw15-tech-' + t.id} className={s.tech}>
                {t.tech}
            </div>
            <div id={'hw15-developer-' + t.id} className={s.developer}>
                {t.developer}
            </div>
        </div>
    ))

    return (
        <div id={'hw15'}>
            <div className={s2.hwTitle}>Homework #15</div>
            <div className={s2.hw}>
                {loading && <div id={'hw15-loading'} className={s.loading}>Loading...</div>}

                <SuperPagination
                    page={page}
                    itemsCountForPage={count}
                    totalCount={totalCount}
                    onChange={handlePageChange}
                />

                <div className={s.rowHeader}>
                    <div className={s.techHeader}>
                        tech
                        <SuperSort sort={sort} value={'tech'} onChange={handleSortChange} />
                    </div>
                    <div className={s.developerHeader}>
                        developer
                        <SuperSort sort={sort} value={'developer'} onChange={handleSortChange} />
                    </div>
                </div>

                {mappedTechs}
            </div>
        </div>
    )
}

export default HW15